### Solución robusta con `pthread_mutex` en C

Para garantizar la exclusión mutua y evitar que los hilos interfieran entre sí, utilizamos un semáforo binario o `mutex` provisto por la librería POSIX threads (`pthread.h`). El mutex actúa como una esclusa o cerrojo: solo un hilo puede adquirirlo a la vez para ejecutar su sección crítica [ref. no verificada].

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define NUM_HILOS 2
#define INCREMENTOS 100000

// Variable global compartida
long contador_global = 0;

// Declaración e inicialización del Mutex
pthread_mutex_t mutex_contador = PTHREAD_MUTEX_INITIALIZER;

// Función que ejecutarán los hilos
void* rutina_hilo(void* arg) {
    for (int i = 0; i < INCREMENTOS; i++) {
        // Cláusula de entrada: Adquisición exclusiva del cerrojo
        if (pthread_mutex_lock(&mutex_contador) != 0) {
            perror("Error al bloquear el mutex");
            pthread_exit(NULL);
        }

        // --- SECCIÓN CRÍTICA ---
        contador_global++;
        // -----------------------

        // Cláusula de salida: Liberación del cerrojo
        if (pthread_mutex_unlock(&mutex_contador) != 0) {
            perror("Error al desbloquear el mutex");
            pthread_exit(NULL);
        }
    }
    return NULL;
}

int main(void) {
    pthread_t hilos[NUM_HILOS];

    // Creación de hilos
    for (int i = 0; i < NUM_HILOS; i++) {
        if (pthread_create(&hilos[i], NULL, rutina_hilo, NULL) != 0) {
            perror("Error al crear el hilo");
            exit(EXIT_FAILURE);
        }
    }

    // Sincronización final: Esperar a que terminen todos los hilos
    for (int i = 0; i < NUM_HILOS; i++) {
        if (pthread_join(hilos[i], NULL) != 0) {
            perror("Error al hacer join del hilo");
            exit(EXIT_FAILURE);
        }
    }

    // Destrucción segura del mutex
    pthread_mutex_destroy(&mutex_contador);

    printf("Valor final esperado: %d\n", NUM_HILOS * INCREMENTOS);
    printf("Valor final obtenido: %ld\n", contador_global);

    return EXIT_SUCCESS;
}
```

