### Ejemplo defensivo en C con validación de nulos

```c
#include <stdio.h>
#include <stdlib.h>

void modificar_puntero(int **puntero_a_modificar, int *nuevo_destino) {
    // Cláusula de guarda defensiva contra punteros nulos
    if (puntero_a_modificar == NULL || nuevo_destino == NULL) {
        return;
    }
    // Modificamos a qué apunta el puntero simple original
    *puntero_a_modificar = nuevo_destino;
}

int main(void) {
    int valor_a = 10;
    int valor_b = 20;
    int *p = &valor_a; // p apunta a valor_a

    printf("Antes: *p apunta a un valor de %d\n", *p);

    // Pasamos la DIRECCIÓN del puntero 'p' (&p), lo que exige un doble puntero (int **)
    modificar_puntero(&p, &valor_b);

    printf("Después: *p ahora apunta a un valor de %d\n", *p);

    return 0;
}
```

